/* ═══════════════════════════════════════════════════════════════════════════
   رحاب المدينة — مجتمع المدينة الرقمي
   Residents & visitors · Discovery · Community · Participation · Plan
   One app with two experiences (resident, visitor) and one conversation Assistant.
   Arabic-first (RTL). AI is horizontal and mostly invisible.
   ═══════════════════════════════════════════════════════════════════════════ */

/* ───────────────────────── 1. DESIGN TOKENS ───────────────────────── */

const T = {
  limestone: "#F5F5F2",          // Marble — shared surface foundation (cool, not ivory)
  paper: "#FFFFFF",              // Card
  sand: "#ECEBE6",               // Stone — quiet surfaces, inputs
  sandDeep: "#DEDCD5",           // Line
  ink: "#1B2027",                // Basalt Ink — shared text anchor
  muted: "#5A6370",              // Slate
  green: "#24548A",
  deep: "#172A46",               // Night Noor
  brass: "#8A5A12",              // Lamp Amber (as text)
  brassSoft: "#F3D79E",          // Canopy Light — the light point, badges on dark
  clay: "#B03D5C",               // Madani Rose — saves, live and unread moments
  ok: "#1E6A60",
  warn: "#A33A2B",
  line: "rgba(27,32,39,.12)",
  lineSoft: "rgba(27,32,39,.07)",
  ar: '"IBM Plex Sans Arabic","Tajawal",Tahoma,Arial,sans-serif',
  en: '"IBM Plex Sans","Inter",system-ui,sans-serif',
  naskh: '"Noto Naskh Arabic","IBM Plex Sans Arabic",serif',
};

/* ── One foundation, two accent themes (Noor) ──
   The pre-sign-in entry (Start, Language, Sign in, Create account, profile setup) uses
   the shared Rihab Madinah brand: Night Noor with Canopy Light. Once an account enters
   the app, its persona's accent theme is applied to the same semantic tokens every
   component already reads, so no screen hard-codes a persona colour:
   the Resident's «نهار المدينة» Daylight (Marble + Grove) and the Visitor's
   «مساء المدينة» Evening light (Night Noor + Canopy glow). Every pair meets WCAG AA.
     accentPrimary   fills: primary buttons, active chips, avatar, toggles
     onAccent        text/icons placed on accentPrimary
     accentText      the accent used as text or an icon on light surfaces
     accentDeep      the deepest accent: hero surfaces carrying light text
     accentSecondary secondary fills and tints
     secondaryText   the secondary accent as text or an icon
     accentTint      quiet accent wash behind selected or highlighted content */
const NIGHT_GLOW = "radial-gradient(120% 70% at 50% 118%, rgba(243,215,158,.30) 0%, rgba(243,215,158,.08) 42%, rgba(243,215,158,0) 64%), linear-gradient(165deg, #172A46 0%, #1E355A 52%, #24406A 100%)";
const BRAND_THEME = {
  green: "#24548A", deep: "#172A46", onDeep: "#F5F5F2", brass: "#8A5A12", brassSoft: "#F3D79E", clay: "#B03D5C",
  heroBg: NIGHT_GLOW, heroInk: "#F5F5F2", heroSub: "#F3D79E",
  heroCtaBg: "#F3D79E", heroCtaInk: "#172A46", heroBadge: "linear-gradient(145deg, #F7E3B8, #F3D79E)", heroBadgeInk: "#172A46",
  tint: "#E6EDF5",
};
const PERSONA_THEME = {
  resident: {
    accentPrimary: "#1E6A60", onAccent: "#FFFFFF", accentText: "#1E6A60", accentDeep: "#154C45",
    accentSecondary: "#9FCDC2", secondaryText: "#24548A", accentTint: "#E6F0EE",
    heroBg: "linear-gradient(165deg, #E4F1EC 0%, #F5F5F2 100%)", heroInk: "#1B2027", heroSub: "#1E6A60",
    heroCtaBg: "#1E6A60", heroCtaInk: "#FFFFFF", heroBadge: "linear-gradient(145deg, #9FCDC2, #1E6A60)", heroBadgeInk: "#FFFFFF",
  },
  visitor: {
    accentPrimary: "#24548A", onAccent: "#FFFFFF", accentText: "#24548A", accentDeep: "#172A46",
    accentSecondary: "#F3D79E", secondaryText: "#8A5A12", accentTint: "#E6EDF5",
    heroBg: NIGHT_GLOW, heroInk: "#F5F5F2", heroSub: "#F3D79E",
    heroCtaBg: "#F3D79E", heroCtaInk: "#172A46", heroBadge: "linear-gradient(145deg, #F7E3B8, #F3D79E)", heroBadgeInk: "#172A46",
  },
};
Object.assign(T, BRAND_THEME, { glass: "rgba(245,245,242,.975)" });
let THEMED = undefined;
/* map a persona onto the semantic tokens (and the older names components use) */
function applyTheme(persona) {
  if (THEMED === (persona || null)) return;
  THEMED = persona || null;
  const p = PERSONA_THEME[persona];
  if (!p) { Object.assign(T, BRAND_THEME, { accentPrimary: BRAND_THEME.deep, onAccent: BRAND_THEME.onDeep, accentText: BRAND_THEME.green, accentDeep: BRAND_THEME.deep, accentSecondary: BRAND_THEME.brassSoft, secondaryText: BRAND_THEME.brass, accentTint: BRAND_THEME.tint }); return; }
  Object.assign(T, p, {
    green: p.accentText, deep: p.accentPrimary, onDeep: p.onAccent, brass: p.secondaryText, brassSoft: p.accentSecondary,
    clay: "#B03D5C", tint: p.accentTint,
  });
}
applyTheme(null);
const themeVars = () => ({
  "--accent-primary": T.accentPrimary, "--accent-secondary": T.accentSecondary, "--accent-deep": T.accentDeep,
  "--on-accent": T.onAccent, "--accent-text": T.accentText, "--surface-base": T.limestone, "--text-primary": T.ink, "--border-soft": T.sand,
});

const R = { ctl: 8, box: 12, boxLg: 14, media: 16, mediaLg: 20, pill: 999 };

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600;700&family=Noto+Naskh+Arabic:wght@600;700&display=swap');

.app *, .app *::before, .app *::after { box-sizing: border-box; }
.app { font-family: ${T.ar}; color: ${T.ink}; -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
.app[dir="ltr"] { font-family: ${T.en}; }
.app .lat { font-family: ${T.en}; }
.app button { font: inherit; color: inherit; cursor: pointer; background: none; border: none; padding: 0; -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
.app input, .app textarea, .app select { font: inherit; color: inherit; }
.app ::-webkit-scrollbar { width: 0; height: 0; }
.app .scroll { scrollbar-width: none; -ms-overflow-style: none; overscroll-behavior-y: contain; }
.app .row { display: flex; align-items: center; }
.app img, .app svg { max-width: 100%; }

/* the phone frame is the layout container: rail cards size against it (cqi), and layout
   containment makes it the containing block for fixed overlays, so sheets and scrims cover
   the visible frame (not the whole browser window) on a wide screen too */
.app [data-phone] { container-type: inline-size; contain: layout; }
/* real-place tiles (logo, category): sized by their own width, so a thumbnail shows
   only the mark and a card or hero also names the kind of place */
.app .vt { container-type: inline-size; }
.app .vt-label { display: none; font-size: 11.5px; font-weight: 700; line-height: 1.35; text-align: center; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@container (min-width: 118px) { .app .vt-label { display: block; } }
/* a small supplied photo fills a card, but in a large frame it is shown whole over a soft
   copy of itself rather than enlarged past its own resolution */
@container (min-width: 300px) { .app .lo-fg { object-fit: contain !important; } }
/* a supplied logo: whole, never stretched, never past its own pixels (2x screens); in a
   large frame it sits smaller and higher, clear of the title over the lower part */
.app .pl-logo { position: absolute; inset: 0; display: grid; place-items: center; padding-bottom: 6%; }
.app .pl-logo img { display: block; width: auto; height: auto; max-width: min(72%, var(--lw)); max-height: min(56%, var(--lh)); object-fit: contain; }
@container (min-width: 300px) { .app .pl-logo { padding-bottom: 20%; } .app .pl-logo img { max-width: min(56%, var(--lw)); max-height: min(36%, var(--lh)); } }
.app { --rail-tile: clamp(144px, calc((100cqi - 40px) / 2.3), 204px); --rail-feature: clamp(236px, calc((100cqi - 28px) / 1.28), 340px); }
.app[dir="rtl"] { --rail-end: left; --rail-start: right; }
.app[dir="ltr"] { --rail-end: right; --rail-start: left; }

/* every screen is a phone screen: nothing may exceed the viewport inline size */
.app .screen { width: 100%; max-width: 100%; overflow-x: clip; }
.app .pad { padding-inline: 16px; }

/* touch: no primary control smaller than a comfortable thumb */
.app .press { transition: transform .16s cubic-bezier(.2,.8,.2,1), opacity .16s ease; }
.app .press:active { transform: scale(.97); opacity: .9; }
.app .lift { transition: transform .22s cubic-bezier(.2,.8,.2,1); }
.app .lift:active { transform: scale(.985); }
.app .tap { position: relative; }
.app .tap::after { content: ""; position: absolute; inset: 50% 50% 50% 50%; width: 44px; height: 44px; transform: translate(50%, -50%); }
.app[dir="ltr"] .tap::after { transform: translate(-50%, -50%); }
/* chevrons are drawn for RTL (back ›, forward ‹); English mirrors them, and the send
   arrow points the way the text runs */
.app[dir="ltr"] svg.lucide-chevron-left, .app[dir="ltr"] svg.lucide-chevron-right, .app[dir="rtl"] svg.lucide-send { transform: scaleX(-1); }
.app input { text-overflow: ellipsis; }
/* the touch area reaches past the 22px pin: inset is measured from the padding box
   (22 − 2×2 border = 18px), so −13px makes it 44px; a selected pin gets 50px */
.app .pin::after { content: ""; position: absolute; inset: -13px; border-radius: 99px; }

/* horizontal rails — direction-agnostic, edge padding inside the scroller so the
   last card can always be reached in both RTL and LTR */
.app .rail {
  display: flex; gap: 12px; overflow-x: auto; overflow-y: hidden;
  padding-inline: 16px; padding-block-end: 4px;
  scroll-snap-type: x proximity; scroll-padding-inline-start: 16px;
  -webkit-overflow-scrolling: touch; touch-action: pan-x pan-y;
  scrollbar-width: none; overscroll-behavior-x: contain;
}
.app .rail::-webkit-scrollbar { display: none; }
.app .rail > * { scroll-snap-align: start; flex: 0 0 auto; }
.app .rail::after { content: ""; flex: 0 0 4px; }
/* edge fades, set by useRailFades only while content actually continues past an edge,
   so a card or chip at the edge reads as "more this way", never as an accidental cut */
.app .rail[data-fade="end"] { -webkit-mask-image: linear-gradient(to var(--rail-end), #000 calc(100% - var(--fade-end, 44px)), transparent); mask-image: linear-gradient(to var(--rail-end), #000 calc(100% - var(--fade-end, 44px)), transparent); }
.app .rail[data-fade="start"] { -webkit-mask-image: linear-gradient(to var(--rail-start), #000 calc(100% - var(--fade-start, 28px)), transparent); mask-image: linear-gradient(to var(--rail-start), #000 calc(100% - var(--fade-start, 28px)), transparent); }
.app .rail[data-fade="both"] { -webkit-mask-image: linear-gradient(to var(--rail-end), transparent 0, #000 var(--fade-start, 28px), #000 calc(100% - var(--fade-end, 44px)), transparent 100%); mask-image: linear-gradient(to var(--rail-end), transparent 0, #000 var(--fade-start, 28px), #000 calc(100% - var(--fade-end, 44px)), transparent 100%); }

.app .clamp1 { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.app .clamp2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.app .clamp3 { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.app .clamp4 { display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }
.app .break { overflow-wrap: anywhere; word-break: break-word; }

@keyframes emUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@keyframes emIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes emSheet { from { transform: translateY(100%); } to { transform: none; } }
@keyframes emScrim { from { opacity: 0; } to { opacity: 1; } }
@keyframes emShimmer { 0% { background-position: 120% 0; } 100% { background-position: -120% 0; } }
@keyframes emSpin { to { transform: rotate(360deg); } }
@keyframes emPush { from { opacity: .4; transform: translateX(var(--push, 18px)); } to { opacity: 1; transform: none; } }
@keyframes emRise { 0% { transform: translateY(0); opacity: 0; } 12% { opacity: 1; } 100% { transform: translateY(-190px); opacity: 0; } }
@keyframes emLangFlowR { to { stroke-dashoffset: 0; } }
@keyframes emLangFlowL { to { stroke-dashoffset: 0; } }
@keyframes noorLit { 0% { opacity: 0; transform: scale(.35); } 60% { opacity: 1; } 100% { opacity: 1; transform: none; } }
.app .noor-lit { animation: noorLit .6s .25s cubic-bezier(.2,.8,.2,1) backwards; }
.app .up { animation: emUp .34s cubic-bezier(.2,.8,.2,1) backwards; }
.app .fade { animation: emIn .3s ease backwards; }
.app .sheetIn { animation: emSheet .3s cubic-bezier(.2,.9,.25,1) backwards; }
.app .scrimIn { animation: emScrim .22s ease backwards; }
.app .spin { animation: emSpin 1s linear infinite; }
.app .push { animation: emPush .26s cubic-bezier(.2,.8,.2,1) backwards; }
.app .shim { background: linear-gradient(90deg, ${T.sand} 25%, ${T.limestone} 50%, ${T.sand} 75%); background-size: 240% 100%; animation: emShimmer 1.4s linear infinite; }

@media (prefers-reduced-motion: reduce) {
  .app .up, .app .fade, .app .sheetIn, .app .scrimIn, .app .shim, .app .spin, .app .push, .app .noor-lit { animation: none !important; }
  .app [style*="emRise"] { animation: none !important; opacity: .35 !important; }
  .app .press, .app .lift { transition: none !important; }
}
`;

