/* English for an Arabic string: the dictionary entry, or — for composed names such as
   "مطعم الركن — العوالي" — the entries of every " — " part; "" when unknown. */
const enText = (v) => {
  if (typeof v !== "string") return "";
  if (EN_TXT[v]) return EN_TXT[v];
  if (!v.includes(" — ")) return "";
  const parts = v.split(" — ");
  return parts.every((x) => EN_TXT[x]) ? parts.map((x) => EN_TXT[x]).join(" — ") : "";
};
const D = (v) => (isEn() && typeof v === "string" ? enText(v) || v : v);
/* an outbound partner's English name as it reads inside a sentence ("the booking platform") */
const partnerEn = (v) => {
  const e = enText(v) || String(v || "");
  if (/^the /i.test(e)) return "the" + e.slice(3);
  return /^(Madinah|University)\b/.test(e) ? e : "the " + e.charAt(0).toLowerCase() + e.slice(1);
};
const Dj = (parts, sep = " — ") => parts.filter(Boolean).map(D).join(sep);

/* A map whose values follow the active language. Call sites stay unchanged:
   SUIT[x] and TYPE_LABEL[x] simply return the right language. */
const bilingual = (arMap, enMap) => new Proxy(arMap, {
  get: (t, k) => (isEn() && enMap && Object.prototype.hasOwnProperty.call(enMap, k) ? enMap[k] : t[k]),
});
