/* The whole product is Arabic-first. English is a full viewing language, not a
   partial veneer: formatting helpers, numerals and direction all follow it. */
let LANG = "ar";
const setLang = (l) => { LANG = l; };
const isEn = () => LANG === "en";
const ar = (v) => (isEn() ? String(v) : String(v).replace(/[0-9]/g, (d) => AR_DIGITS[+d]));
/* pick between an Arabic and an English literal at a call site */
const tx = (a, e) => (isEn() ? e : a);
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const uniq = (a) => Array.from(new Set(a));
const byId = (list) => { const m = {}; for (const x of list) m[x.id] = x; return m; };

/* deterministic hash → pseudo random, so every object looks stable across renders */
function hash(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0);
}
function rng(seed) {
  let s = typeof seed === "string" ? hash(seed) : seed >>> 0;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
}
const pick = (arr, r) => arr[Math.floor(r() * arr.length) % arr.length];

/* time helpers. "Now" is the real clock. Sample schedules are written as offsets from
   an anchor — today's date in Madinah at 18:20 — so the clock times they were designed
   with stay the same whichever day the app is opened. Offers run on one demo
   calendar and renew themselves when they expire (see OFFER_SLOTS).
   QA can pin the clock with window.RIHAB_MADINAH_NOW (an ISO time) before the app loads. */
const MIN = 60000, HOUR = 3600000, DAY = 86400000;
const NOW = (() => {
  const pin = typeof window !== "undefined" ? window.RIHAB_MADINAH_NOW : null;
  const d = pin ? new Date(pin) : new Date();
  return isNaN(d) ? new Date() : d;
})();
const t0 = NOW.getTime();
const ANCHOR = (() => { const l = new Date(t0 + 3 * HOUR); return Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate(), 18, 20) - 3 * HOUR; })();
const at = (offsetHours) => new Date(ANCHOR + offsetHours * HOUR);
/* every offer is fictional demo content: all start on 1 Sep 2026 and their end dates are
   spread from 1 Nov 2026 to 30 Apr 2027, in the order they were written */
const OFFER_START = Date.parse("2026-09-01T00:00:00+03:00");
const OFFER_FIRST_END = Date.parse("2026-11-01T23:59:00+03:00");
const OFFER_LAST_END = Date.parse("2027-04-30T23:59:00+03:00");
const daysAgo = (d) => new Date(t0 - d * DAY);

/* Madinah runs on UTC+03:00 with no daylight saving. The prototype must read the
   clock in Madinah time whatever timezone the device or server happens to use. */
const TZ = 3 * HOUR;
const mk = (d) => new Date(new Date(d).getTime() + TZ);   // read with getUTC*
const mkHour = (d = NOW) => { const l = mk(d); return l.getUTCHours() + l.getUTCMinutes() / 60; };
const mkDayStart = (d) => { const l = mk(d); return Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate()); };

const AR_DAYS = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
const AR_MONTHS = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
const EN_DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const EN_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function clockAr(d) {
  const l = mk(d);
  const h = l.getUTCHours(), m = l.getUTCMinutes();
  const hh = h % 12 === 0 ? 12 : h % 12;
  if (isEn()) return `${hh}${m ? ":" + String(m).padStart(2, "0") : ""} ${h < 12 ? "AM" : "PM"}`;
  return `${ar(hh)}${m ? ":" + ar(String(m).padStart(2, "0")) : ""} ${h < 12 ? "ص" : "م"}`;
}
function dayLabelAr(d) {
  const l = mk(d);
  const diff = Math.round((mkDayStart(d) - mkDayStart(NOW)) / DAY);
  const en = isEn();
  if (diff === 0) return en ? "Today" : "اليوم";
  if (diff === 1) return en ? "Tomorrow" : "غدًا";
  if (diff === -1) return en ? "Yesterday" : "أمس";
  if (diff > 1 && diff < 7) return en ? EN_DAYS[l.getUTCDay()] : AR_DAYS[l.getUTCDay()];
  if (diff < -1 && diff > -7) return en ? `last ${EN_DAYS[l.getUTCDay()]}` : `${AR_DAYS[l.getUTCDay()]} الماضي`;
  return en ? `${EN_MONTHS[l.getUTCMonth()]} ${l.getUTCDate()}` : `${ar(l.getUTCDate())} ${AR_MONTHS[l.getUTCMonth()]}`;
}
function whenAr(d) { return `${dayLabelAr(d)} — ${clockAr(d)}`; }
/* the same, read inside an English sentence ("Until today — 11:59 PM") */
const midEn = (w) => (isEn() ? w.replace(/^(Today|Tomorrow|Yesterday)\b/, (x) => x.toLowerCase()) : w);
const whenMid = (d) => midEn(whenAr(d));
const plural = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`;
/* Arabic number agreement: 1 and 2 take their own forms, 3–10 the plural, 11+ the singular */
const AR_UNITS = {
  minute: ["دقيقة واحدة", "دقيقتين", "دقائق", "دقيقة"], hour: ["ساعة واحدة", "ساعتين", "ساعات", "ساعة"],
  day: ["يوم واحد", "يومين", "أيام", "يومًا"], month: ["شهر واحد", "شهرين", "أشهر", "شهرًا"], year: ["سنة واحدة", "سنتين", "سنوات", "سنة"],
};
function arCount(n, unit, { bare = false } = {}) {
  const [one, two, few, many] = AR_UNITS[unit];
  if (n === 1) return bare ? one.split(" ")[0] : one;
  if (n === 2) return two;
  return `${ar(n)} ${n >= 3 && n <= 10 ? few : many}`;
}
function agoAr(d) {
  const diff = t0 - new Date(d).getTime();
  const en = isEn();
  if (diff < HOUR) { const n = Math.max(1, Math.round(diff / MIN)); return en ? `${plural(n, "minute")} ago` : `قبل ${arCount(n, "minute", { bare: true })}`; }
  if (diff < DAY) { const n = Math.round(diff / HOUR); return en ? `${plural(n, "hour")} ago` : `قبل ${arCount(n, "hour", { bare: true })}`; }
  const dd = Math.round(diff / DAY);
  if (dd < 30) return en ? `${plural(dd, "day")} ago` : `قبل ${arCount(dd, "day", { bare: true })}`;
  if (dd < 365) { const n = Math.round(dd / 30); return en ? `${plural(n, "month")} ago` : `قبل ${arCount(n, "month", { bare: true })}`; }
  const n = Math.round(dd / 365);
  return en ? `${plural(n, "year")} ago` : `قبل ${arCount(n, "year", { bare: true })}`;
}
function inAr(d) {
  const diff = new Date(d).getTime() - t0;
  const en = isEn();
  if (diff <= 0) return en ? "now" : "الآن";
  if (diff < HOUR) { const n = Math.max(1, Math.round(diff / MIN)); return en ? `in ${plural(n, "minute")}` : `بعد ${arCount(n, "minute", { bare: true })}`; }
  if (diff < DAY) { const n = Math.round(diff / HOUR); return en ? `in ${plural(n, "hour")}` : `بعد ${arCount(n, "hour", { bare: true })}`; }
  return dayLabelAr(new Date(d));
}
const riyal = (n) => (n === 0 ? tx("مجانًا", "Free") : tx(`${ar(n)} ريال`, `SAR ${n}`));
/* the price line for an object: its amount, or — when the price has no stated unit — who to ask */
const priceLabel = (o) => (o.priceOnRequest ? tx("السعر لدى مقدّم الخدمة", "Price from the provider") : o.price != null ? riyal(o.price) : null);
const minutesAr = (n) => tx(arCount(n, "minute"), `${n} min`);
/* a span of time as people say it, for the Assistant: «ساعتين ونص», «٣ ساعات», "2 hours 30 min" */
const spanAr = (n) => {
  const h = Math.floor(n / 60), m = Math.round((n % 60) / 5) * 5;
  if (!h) return minutesAr(n);
  const hs = tx(h === 1 ? "ساعة" : arCount(h, "hour"), `${h} ${h === 1 ? "hour" : "hours"}`);
  if (!m) return hs;
  return tx(`${hs} ${m === 30 ? "ونص" : m === 15 ? "وربع" : `و${arCount(m, "minute")}`}`, `${hs} ${m} min`);
};
/* Arabic counts: 1 and 2 have their own forms, 3–10 take the plural */
function countAr(n, one, two, many, singular, en) {
  if (isEn()) {
    const noun = EN_NOUN[singular || one] || EN_NOUN[one] || (singular || one);
    return `${n} ${n === 1 ? noun : (EN_PLURAL[noun] || noun + "s")}`;
  }
  if (n === 1) return one;
  if (n === 2) return two;
  return `${ar(n)} ${n >= 3 && n <= 10 ? many : (singular || one)}`;
}
/* singular Arabic noun → English noun, and its plural */
const EN_NOUN = {
  "نتيجة": "result", "عنصر": "item", "مجتمع": "community", "إجابة": "answer", "محطة": "stop",
  "مساهمة": "contribution", "بلاغ": "report", "حساب": "account", "تصحيح": "correction", "مصدر": "source",
  "نتيجة واحدة": "result", "عنصر واحد": "item", "مجتمع واحد": "community", "إجابة واحدة": "answer",
  "محطة واحدة": "stop", "مساهمة واحدة": "contribution", "بلاغ واحد": "report", "حساب واحد": "account",
  "تصحيح واحد": "correction", "مصدر واحد": "source",
};
const EN_PLURAL = { community: "communities" };

