/* the branches that are a known brand, by record id */
const BRAND_OF = {
  "PLC-022": "starbucks", "PLC-023": "starbucks", "PLC-002": "burgerking", "PLC-015": "mcdonalds",
};
const brandMarkOf = (id) => BRAND_MARKS[BRAND_OF[id]] || null;

/* Context photographs — only for places whose own record says they are inside the
   complex or district a photograph shows. A place merely near a landmark gets none;
   no Madinah place currently needs one. */
const CONTEXT_OF = {};

/* Category visuals — a drawn tile for the kind of place, picked from what the record
   itself says (its kind and its name). Colour is never the only cue: each kind has its
   own icon and its kind label. */
const TILE_TONES = {
  food: { a: "#F7EAEE", b: "#EED6DE", ink: "#8E2F4A" },
  cafe: { a: "#F7EFDF", b: "#EEDFC0", ink: "#6E4810" },
  sweet: { a: "#F8ECF0", b: "#F0D9E1", ink: "#93324F" },
  market: { a: "#F6F0E1", b: "#ECE0C3", ink: "#6B4A14" },
  book: { a: "#E9EFF6", b: "#D6E1EE", ink: "#24548A" },
  green: { a: "#E6F1EE", b: "#CFE4DE", ink: "#1E6A60" },
  heritage: { a: "#F4EEE2", b: "#E7DCC4", ink: "#6B4E1E" },
  civic: { a: "#E9EDF2", b: "#D7DEE7", ink: "#3B5577" },
};
function venueKind(o) {
  const nm = String(o.n || o.name || ""), kd = String(o.t || o.tagline || ""), all = `${nm} ${kd}`;
  const T_ = TILE_TONES;
  if (o.category === "cafe" || /مقهى|محمصة|كافيه|كوفي/.test(all)) return { Icon: Coffee, tone: T_.cafe };
  if (/حلويات|حلاوة|كيك|مخبز|مخابز/.test(all)) return { Icon: /مخبز|مخابز/.test(all) ? Croissant : CakeSlice, tone: T_.sweet };
  if (/مكتبة/.test(all) && o.category === "market") return { Icon: BookOpen, tone: T_.book };
  if (o.category !== "food" && /سوبرماركت|هايبر/.test(all)) return { Icon: ShoppingCart, tone: T_.market };
  if (o.category !== "food" && /مركز|مول|سوق|أسواق/.test(all)) return { Icon: ShoppingBag, tone: T_.market };
  if (o.category === "food") {
    if (/أسماك|بحرية|البحر|البحار|سمك/.test(all)) return { Icon: Fish, tone: T_.food };
    if (/بيتزا/.test(all)) return { Icon: Pizza, tone: T_.food };
    if (/برجر/.test(all)) return { Icon: Sandwich, tone: T_.food };
    if (/بروست|بروستد|الفروج|الطازج|البيك/.test(all)) return { Icon: Drumstick, tone: T_.food };
    if (/فلافل/.test(all)) return { Icon: Sandwich, tone: T_.food };
    if (/فول/.test(all)) return { Icon: Soup, tone: T_.food };
    if (/وجبات سريعة/.test(all)) return { Icon: Sandwich, tone: T_.food };
    return { Icon: Utensils, tone: T_.food };
  }
  if (o.category === "family" || /حديقة/.test(all)) return { Icon: Trees, tone: T_.green };
  if (o.category === "sport") return { Icon: /رياضية|ملعب/.test(all) ? Trophy : Footprints, tone: T_.green };
  if (o.category === "nature") return { Icon: Mountain, tone: T_.heritage };
  if (/قطار|محطة/.test(all)) return { Icon: TrainFront, tone: T_.civic };
  if (/بئر/.test(all)) return { Icon: Droplets, tone: T_.heritage };
  if (o.category === "learn") return { Icon: BookOpen, tone: T_.book };
  if (o.category === "stay") return { Icon: Hotel, tone: T_.civic };
  return { Icon: Landmark, tone: T_.heritage };
}
/* the lattice behind a category visual: an eight-point star on a square grid */
function TileLattice({ ink }) {
  const id = useId().replace(/:/g, "");
  return (
    <svg aria-hidden="true" width="100%" height="100%" style={{ position: "absolute", inset: 0 }}>
      <defs>
        <pattern id={id} width="34" height="34" patternUnits="userSpaceOnUse">
          <g fill="none" stroke={ink} strokeWidth="1" opacity=".12">
            <rect x="7" y="7" width="20" height="20" />
            <rect x="7" y="7" width="20" height="20" transform="rotate(45 17 17)" />
          </g>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill={`url(#${id})`} />
    </svg>
  );
}
function VenueTile({ seed }) {
  const o = OBJ[seed];
  const logo = placeLogoOf(seed);
  if (logo) {
    /* the mark at no more than its own pixel size (2x screens), never stretched or cropped */
    return (
      <div aria-hidden="true" className="vt" style={{ position: "absolute", inset: 0, background: logo.bg }}>
        <div className="pl-logo" style={{ "--lw": `${Math.round(logo.w / 2)}px`, "--lh": `${Math.round(logo.h / 2)}px` }}>
          <img src={logo.src} alt="" loading="lazy" />
        </div>
      </div>
    );
  }
  const mark = brandMarkOf(seed);
  if (mark) {
    return (
      <div aria-hidden="true" className="vt" style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", background: mark.bg }}>
        <div style={{ display: "grid", placeItems: "center" }}>
          <svg viewBox="0 0 24 24" style={{ width: "min(36cqi, 76px)", height: "min(36cqi, 76px)" }}><path d={mark.d} fill={mark.fg} /></svg>
        </div>
      </div>
    );
  }
  const { Icon, tone } = venueKind(o || {});
  return (
    <div aria-hidden="true" className="vt" style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", background: `linear-gradient(150deg, ${tone.a} 0%, ${tone.b} 100%)` }}>
      <TileLattice ink={tone.ink} />
      <div style={{ position: "relative", display: "grid", placeItems: "center", gap: "5cqi", maxWidth: "88%" }}>
        <div style={{ width: "min(34cqi, 72px)", height: "min(34cqi, 72px)", borderRadius: 99, background: "rgba(255,255,255,.88)", display: "grid", placeItems: "center", color: tone.ink, boxShadow: "0 6px 14px -8px rgba(16,24,40,.45)" }}>
          <Icon style={{ width: "52%", height: "52%" }} strokeWidth={1.8} />
        </div>
        <div className="vt-label" style={{ color: tone.ink }}>{o?.tagline && String(o.tagline).length <= 20 ? o.tagline : (CAT[o?.category]?.name || "")}</div>
      </div>
    </div>
  );
}
function Photo({ kind, seed, photo, ratio = "4 / 3", radius = R.media, children, style, scrim = "soft" }) {
  const [failed, setFailed] = useState(false);
  if (EXACT_PHOTO_ONLY.has(seed) && !ownPhoto(seed, photo)) {
    return (
      <div data-media={placeLogoOf(seed) || brandMarkOf(seed) ? "logo" : "category"} style={{ position: "relative", width: "100%", aspectRatio: ratio, borderRadius: radius, overflow: "hidden", background: T.sand, ...style }}>
        <VenueTile seed={seed} />
        {scrim === "strong" && <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(0,0,0,0) 38%, rgba(12,18,30,.64) 100%)" }} />}
        {children}
      </div>
    );
  }
  const slot = photo && PHOTO_DATA[photo] ? photo : photoForKind(kind, seed);
  const real = slot ? REAL_PHOTOS[slot] : null;
  const showReal = real && !failed;
  const lowRes = showReal && !!placePhotoOf(slot)?.lo;
  return (
    <div data-media={showReal ? "photo" : "drawn"} className={lowRes ? "vt" : undefined} style={{ position: "relative", width: "100%", aspectRatio: ratio, borderRadius: radius, overflow: "hidden", background: T.sand, ...style }}>
      <div style={{ position: "absolute", inset: 0 }}><Scene kind={kind} seed={seed} /></div>
      {lowRes && (
        <img src={real.url} alt="" aria-hidden="true" className="lo-bg"
          style={{ position: "absolute", inset: "-8%", width: "116%", height: "116%", objectFit: "cover", filter: "blur(16px) saturate(1.1)" }} />
      )}
      {showReal && (
        <img src={real.url} alt="" loading="lazy" onError={() => setFailed(true)} className={lowRes ? "lo-fg" : undefined}
          style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
      )}
      {scrim !== "none" && (
        <div style={{
          position: "absolute", inset: 0,
          background: scrim === "strong"
            ? "linear-gradient(180deg, rgba(23,42,70,.04) 0%, rgba(16,24,40,.1) 40%, rgba(12,18,30,.58) 100%)"
            : "linear-gradient(180deg, rgba(16,24,40,0) 48%, rgba(12,18,30,.42) 100%)",
        }} />
      )}
      {children}
    </div>
  );
}

