PROVIDERS.forEach((p) => { const nm = p.name, kd = p.kind, bl = p.blurb;
  Object.defineProperty(p, "name", { enumerable: true, get: () => D(nm) });
  Object.defineProperty(p, "kind", { enumerable: true, get: () => D(kd) });
  Object.defineProperty(p, "blurb", { enumerable: true, get: () => D(bl) });
});
const PROV = byId(PROVIDERS);

/* ───────── 4.4 Inventory objects ─────────
   Compact authoring shape, expanded by `expand()` into the full object used by
   every surface. Fields:
   id · n name · t tagline · ab about · nb neighborhood · cat category
   pr provider · sc scene · pt real-photo key · real (real public entity)
   price · dur minutes · su suitability · act action kind · out outbound partner
   tm timing · fx practical facts [label, value, sourceClass, ageDays, freshness]
   com communities · nov novelty · pop popularity · cap/joined declared prototype counts
   ───────────────────────────────────────────────────────────────────────── */

const HOURS = (open, close) => ({ kind: "hours", open, close });
const SESSION = (hoursFromNow, durMin) => ({ kind: "session", start: at(hoursFromNow), end: at(hoursFromNow + durMin / 60) });
const WEEKLY = (dayIdx, hour, minute = 0) => ({ kind: "recurring", dayIdx, hour, minute });
/* every other week, counted from a fixed first meeting (a Madinah date) */
const FORTNIGHTLY = (dayIdx, hour, first) => ({ kind: "recurring", dayIdx, hour, minute: 0, every: 2, first });
/* the nth such weekday of each month (1 = the first) */
const MONTHLY = (nth, dayIdx, hour) => ({ kind: "recurring", dayIdx, hour, minute: 0, nth });
/* a one-off session at a written clock time, `day` days after today (Madinah time) */
const ON = (day, hh, mm, durMin) => {
  const start = ANCHOR - (18 * 60 + 20) * MIN + day * DAY + (hh * 60 + mm) * MIN;
  return { kind: "session", start: new Date(start), end: new Date(start + durMin * MIN) };
};
/* a one-off session on the coming given weekday (today counts) at a written clock time */
const ON_NEXT = (dayIdx, hh, mm, durMin) => ON((dayIdx - new Date(ANCHOR + TZ).getUTCDay() + 7) % 7, hh, mm, durMin);
const WINDOW = (fromDays, toDays) => ({ kind: "window", from: at(fromDays * 24), to: at(toDays * 24) });
/* an offer's validity: its dates come from the demo calendar (OFFER_SLOTS) — the end
   date the content workbook gives (`until`); the number only orders it among the others */
const OFFER_WINDOW = (fromDays, toDays, until) => ({ kind: "window", offerOrder: toDays, until: until || null, from: new Date(OFFER_START), to: new Date(OFFER_FIRST_END) });

