/* ═══════════════════════════════════════════════════════════════════════════
   PARTICIPATION & GOING OUT
   From "this looks interesting" to actually going, joining, completing and
   continuing. Outings are assembled from context, never static itineraries.
   ═══════════════════════════════════════════════════════════════════════════ */

const OUTING_SHAPES = [
  { id: "coffee-workshop-dinner", title: "قهوة ← ورشة ← عشاء", hours: 4,
    steps: [{ cat: ["cafe"], dur: 45 }, { type: ["activity", "experience"], dur: 120 }, { cat: ["food"], dur: 60 }] },
  { id: "culture-walk-food", title: "معرض ← مشية قصيرة ← أكل قريب", hours: 3.5,
    steps: [{ cat: ["culture"], dur: 70 }, { cat: ["heritage", "market"], dur: 60 }, { cat: ["food"], dur: 55 }] },
  { id: "market-sweets", title: "سوق ← حلو بعد العشاء", hours: 2,
    steps: [{ cat: ["market"], dur: 50 }, { cat: ["food", "cafe"], dur: 40 }] },
  { id: "family-evening", title: "نشاط للأطفال ← عشاء عائلي", hours: 3,
    steps: [{ cat: ["family"], dur: 80 }, { cat: ["food"], dur: 60 }] },
  { id: "quiet-solo", title: "مشي هادئ ← قهوة لوحدك", hours: 2,
    steps: [{ cat: ["sport", "nature"], dur: 50 }, { cat: ["cafe"], dur: 45 }] },
  { id: "learn-then-eat", title: "جلسة تعلّم ← عشاء خفيف", hours: 3,
    steps: [{ cat: ["learn", "craft"], dur: 90 }, { cat: ["food"], dur: 45 }] },
];

/* a visitor's day in Madinah starts from its landmarks: a must-see, then something close to it */
const VISITOR_SHAPES = [
  { id: "landmarks-day", title: "معلم ← وجبة قريبة ← معلم آخر", hours: 6,
    steps: [{ must: true, dur: 75 }, { cat: ["food"], dur: 60 }, { must: true, dur: 60 }] },
  { id: "landmark-museum", title: "معلم ← متحف قريب ← قهوة", hours: 4,
    steps: [{ must: true, dur: 60 }, { cat: ["culture"], dur: 70 }, { cat: ["cafe", "food"], dur: 40 }] },
  { id: "landmark-meal", title: "معلم ← وجبة قريبة", hours: 2.5,
    steps: [{ must: true, dur: 60 }, { cat: ["food", "cafe"], dur: 50 }] },
];

function buildOutings(ctx, state, maxHours = 4, opts = {}) {
  const out = [];
  const usedShapes = (opts.landmarks ? [...VISITOR_SHAPES, ...OUTING_SHAPES] : OUTING_SHAPES).filter((sh) => sh.hours <= maxHours + 0.5);
  for (const shape of usedShapes) {
    const chosen = [];
    const taken = new Set();
    let ok = true;
    for (const st of shape.steps) {
      const pool = INVENTORY.filter((o) =>
        !taken.has(o.id) && !(opts.exclude || []).includes(o.id) && isPromotable(o) && o.type !== "offer" && o.type !== "service" &&
        !(opts.everyone && o.suit.includes("women") && !ctx.womenOnly) &&
        (st.must ? MUST_DO_SET.has(o.id) && !!o.geo : true) && (opts.landmarks && !chosen.length && !o.geo ? false : true) &&
        (st.cat ? st.cat.includes(o.category) : true) && (st.type ? st.type.includes(o.type) : true) &&
        (chosen.length ? distanceKm(o, chosen[0].geo) < 5 : true) &&
        (ctx.party === "kids" ? !["cafe"].includes(o.category) : true));
      if (!pool.length) { ok = false; break; }
      /* a landmark day keeps its later stops a short walk or ride from where it started */
      const close = opts.landmarks && chosen[0]?.geo ? pool.filter((o) => distanceKm(o, chosen[0].geo) < 2) : [];
      const best = rank(close.length ? close : pool, ctx, { limit: 3, maxPerCategory: 3, maxPerNeighborhood: 3 })[0];
      if (!best) { ok = false; break; }
      taken.add(best.o.id);
      chosen.push(best.o);
    }
    if (!ok || chosen.length < 2) continue;
    const mins = chosen.reduce((a, o) => a + (o.duration || 50), 0) + (chosen.length - 1) * 15;
    out.push({ ...shape, objects: chosen, minutes: mins });
  }
  return out.slice(0, 3);
}

function OutingSheet({ outing, open, onClose }) {
  const { dispatch, go, toast } = useApp();
  if (!outing) return null;
  const addAll = () => {
    outing.objects.forEach((o) => dispatch({ type: "plan", obj: o.id }));
    toast("أضفنا الخطة كاملة — لم يُحجز أي شيء بعد");
    onClose(); go({ s: "plan" });
  };
  return (
    <Sheet open={open} onClose={onClose} title={outing.title} tall>
      <div style={{ fontSize: 13, color: T.muted, lineHeight: 1.8, marginBottom: 14 }}>
        مقترح مبني على وقتك وحيّك وما تفاعلت معه — وليس قالبًا جاهزًا. يمكنك حذف أي محطة.
      </div>
      {outing.objects.map((o, i) => (
        <div key={o.id} className="row" style={{ gap: 12, alignItems: "flex-start", marginBottom: 14 }}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", flex: "0 0 24px", paddingTop: 4 }}>
            <span style={{ width: 24, height: 24, borderRadius: 99, background: T.deep, color: T.onDeep, fontSize: 12, fontWeight: 800, display: "grid", placeItems: "center" }}>{ar(i + 1)}</span>
            {i < outing.objects.length - 1 && <span style={{ width: 2, flex: 1, minHeight: 34, background: T.sand, marginTop: 4 }} />}
          </div>
          <button className="lift" onClick={() => { onClose(); go({ s: "object", id: o.id }); }} style={{ flex: 1, textAlign: "start", minWidth: 0 }}>
            <div className="clamp1" style={{ fontSize: 14.5, fontWeight: 800 }}>{o.name}</div>
            <div style={{ fontSize: 12, color: T.muted, marginTop: 3 }}>
              {Dj([NB[o.neighborhood]?.name, o.duration ? minutesAr(o.duration) : null, priceLabel(o)])}
            </div>
          </button>
          <div style={{ width: 56, flex: "0 0 56px" }}>
            <Photo kind={o.scene} seed={o.id} photo={o.photo} ratio="1 / 1" radius={R.ctl} scrim="none" />
          </div>
        </div>
      ))}
      <div style={{ padding: "11px 12px", borderRadius: R.box, background: T.sand, fontSize: 12.5, color: T.muted, lineHeight: 1.8, marginTop: 4 }}>
        الوقت التقديري {minutesAr(outing.minutes)} شاملًا التنقل بين المحطات. الإضافة إلى خطتك لا تعني حجزًا ولا تسجيلًا.
      </div>
      <button className="press" onClick={addAll}
        style={{ width: "100%", marginTop: 16, padding: "13px", borderRadius: R.ctl, background: T.deep, color: T.onDeep, fontWeight: 800, fontSize: 14 }}>
        أضف الخطة كاملة إلى خطتي
      </button>
    </Sheet>
  );
}

function OutingCard({ outing, onOpen }) {
  return (
    <button className="lift" onClick={onOpen} style={{ width: "var(--rail-feature)", textAlign: "start" }}>
      <div style={{ display: "flex", gap: 4, borderRadius: R.media, overflow: "hidden" }}>
        {outing.objects.map((o) => (
          <div key={o.id} style={{ flex: 1 }}>
            <Photo kind={o.scene} seed={o.id} photo={o.photo} ratio="3 / 4" radius={0} scrim="soft" />
          </div>
        ))}
      </div>
      <div style={{ fontSize: 14.5, fontWeight: 800, marginTop: 8 }}>{outing.title}</div>
      <div style={{ fontSize: 12, color: T.muted, marginTop: 3 }}>
        {countAr(outing.objects.length, "محطة واحدة", "محطتان", "محطات", "محطة")} — {minutesAr(outing.minutes)}
      </div>
    </button>
  );
}

/* Participation context — stated by the organiser, never inferred. */
function ParticipationContext({ o, compact }) {
  /* "first time? here's what to expect" speaks of a next time — not for something that is over or paused */
  if (NOT_RUNNING.includes(lifecycleOf(o))) return null;
  const bits = [];
  if (o.capacity != null) bits.push({ icon: Users, text: tx(`${ar(o.joinedCount)} من ${ar(o.capacity)} مشاركًا`, `${o.joinedCount} of ${o.capacity} joined`) });
  const next = nextOccurrence(o);
  if (next) bits.push({ icon: Clock, text: whenAr(next) });
  if (o.duration) bits.push({ icon: Clock, text: minutesAr(o.duration) });
  o.suit.filter((x) => ["small", "solo", "beginners", "noexp", "women", "kids", "family", "students", "arabic", "bilingual"].includes(x))
    .forEach((x) => bits.push({ icon: Check, text: SUIT[x] }));
  if (!bits.length) return null;
  return (
    <div style={{ padding: compact ? 0 : "13px", borderRadius: R.box, background: compact ? "transparent" : T.sand, marginTop: compact ? 8 : 14 }}>
      {!compact && <div style={{ fontSize: 13, fontWeight: 800, marginBottom: 9 }}>أول مرة؟ هذا ما تتوقعه</div>}
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
        {bits.slice(0, 6).map((b, i) => (
          <span key={i} className="row" style={{ gap: 5, fontSize: 12, color: T.ink, fontWeight: 600 }}>
            <b.icon size={12.5} color={T.green} />{b.text}
          </span>
        ))}
      </div>
    </div>
  );
}

/* Completion — lightweight, high-value prompts instead of a star rating. */
function CompletionSheet({ o, open, onClose }) {
  const { dispatch, go, toast, ctx, state } = useApp();
  const [ask, setAsk] = useState(false);
  if (!o) return null;
  const next = rank(INVENTORY.filter((x) => x.id !== o.id && isPromotable(x)),
    { ...ctx, noveltySeeking: true, planNeighborhoods: [o.neighborhood] }, { limit: 3, maxPerCategory: 1 });
  const openQ = allContributions(state).find((k) => k.type === "question" && !k.answers && k.communities.some((c) => o.communities.includes(c)));

  return (
    <>
      <Sheet open={open && !ask} onClose={onClose} title={tx(`أكملت «${o.name}»`, `You completed \u201c${D(o.name)}\u201d`)} tall>
        <div style={{ fontSize: 14, lineHeight: 1.85, marginBottom: 16 }}>استمتعت؟ سطران منك الآن أنفع لغيرك من عشرة تقييمات بالنجوم.</div>
        {[
          { icon: Camera, label: "شارك صورة", note: "صورة حديثة تساعد من لم يزره بعد", act: () => setAsk(true) },
          { icon: Sparkles, label: "اكتب نصيحة عملية", note: "أفضل وقت، ما تطلبه، أو ما تمنيت معرفته", act: () => setAsk(true) },
          openQ && { icon: HelpCircle, label: "ساعد شخصًا يسأل", note: openQ.body.slice(0, 60) + "…", act: () => { onClose(); go({ s: "thread", id: openQ.id }); } },
        ].filter(Boolean).map((row, i) => (
          <button key={i} className="press" onClick={row.act}
            style={{ display: "flex", width: "100%", gap: 11, textAlign: "start", padding: "13px 0", borderBottom: `1px solid ${T.lineSoft}`, alignItems: "flex-start" }}>
            <row.icon size={17} color={T.green} style={{ marginTop: 2 }} />
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 14, fontWeight: 800 }}>{row.label}</div>
              <div className="clamp1" style={{ fontSize: 12, color: T.muted, marginTop: 3 }}>{row.note}</div>
            </div>
            <ChevronLeft size={15} color={T.muted} style={{ marginTop: 3 }} />
          </button>
        ))}

        {next.length > 0 && (
          <div style={{ marginTop: 20 }}>
            <div style={{ fontSize: 13.5, fontWeight: 800, marginBottom: 4 }}>خطوة تالية تناسبك</div>
            <div style={{ fontSize: 12, color: T.muted, marginBottom: 10 }}>لن نعرض عليك نفس التجربة مرة أخرى.</div>
            <div className="rail scroll" style={{ gap: 12, marginInline: -16 }}>
              {next.map((x) => <TileCard key={x.o.id} x={x} />)}
            </div>
          </div>
        )}
        <button className="press" onClick={onClose}
          style={{ width: "100%", marginTop: 18, padding: "12px", borderRadius: R.ctl, background: T.paper, border: `1px solid ${T.line}`, fontWeight: 800, fontSize: 13.5 }}>
          لاحقًا
        </button>
      </Sheet>
      <AskSheet open={ask} onClose={() => { setAsk(false); onClose(); }} presetObject={o} />
    </>
  );
}

/* ═══════════════════════════════════════════════════════════════════════════
   HOME — a contextual compositor, not a menu
   Precedence: active plan → time-critical → immediate/nearby → community →
   personalized discovery → offers → inspiration → participation.
   Modules are chosen, not all rendered.
   ═══════════════════════════════════════════════════════════════════════════ */

function greeting() {
  const h = Math.floor(mkHour());
  if (h < 5) return tx("ليلة هادئة", "A quiet night");
  if (h < 11) return tx("صباح الخير", "Good morning");
  if (h < 15) return tx("نهارك سعيد", "Good afternoon");
  return tx("مساء الخير", "Good evening");
}


/* ───────── Deal presentation — one visual language for every surface ───────── */
const DEAL = { ink: "#9A3F1E", bg: "#FBEBDD", solid: "#B4532A" };

function DealBadge({ o, of: given, onPhoto, short, style }) {
  const of = given || offerFor(o);
  if (!of) return null;
  const ending = offerStatus(of) === "ending";
  return (
    <span className="row" style={{
      gap: 4, fontSize: 11, fontWeight: 800, lineHeight: 1.5, whiteSpace: "nowrap", borderRadius: R.pill,
      padding: "2px 8px", color: onPhoto ? "#F5F5F2" : DEAL.ink, background: onPhoto ? DEAL.solid : DEAL.bg,
      boxShadow: onPhoto ? "0 4px 10px -4px rgba(40,10,20,.5)" : "none", maxWidth: "100%", overflow: "hidden", textOverflow: "ellipsis", ...style,
    }}>
      {/* on a photo the badge stays short; validity is printed under the photo */}
      <Tag size={11} strokeWidth={2.4} style={{ flexShrink: 0 }} />{L2(of.badge)}{ending && !onPhoto && !short ? <span style={{ opacity: .85 }}>· {tx("ينتهي قريبًا", "ends soon")}</span> : null}
    </span>
  );
}

/* compact line under a card's metadata: value, price, validity, exclusivity */
function DealLine({ o, of: given, compact }) {
  const of = given || offerFor(o);
  if (!of) return null;
  const p = offerPrice(of);
  return (
    <div style={{ marginTop: 6, display: "flex", flexWrap: "wrap", alignItems: "center", gap: "3px 7px", fontSize: 11.5, fontWeight: 700, color: DEAL.ink, lineHeight: 1.55 }}>
      <DealBadge of={of} short />
      {compact && offerStatus(of) === "ending" && <span style={{ color: T.warn }}>{tx("ينتهي قريبًا", "Ends soon")}</span>}
      {p && <span><b style={{ fontWeight: 800 }}>{riyal(p.now)}</b> <s style={{ color: T.muted, fontWeight: 600 }}>{riyal(p.was)}</s>{p.pkg ? <span style={{ color: T.muted, fontWeight: 600 }}> {L2(PKG_NOTE)}</span> : null}</span>}
      {!compact && of.exclusive && <span style={{ color: T.green }}>{tx("حصري عبر رحاب المدينة", "Rihab Madinah exclusive")}</span>}
      {!compact && <span style={{ color: offerStatus(of) === "ending" ? T.warn : T.muted, fontWeight: 600 }}>{offerExpiry(of)}</span>}
    </div>
  );
}

/* decision-page panel: everything that decides whether the deal is worth it */
function DealPanel({ o }) {
  const of = offerFor(o);
  if (!of) return null;
  const p = offerPrice(of);
  const st = offerStatus(of);
  return (
    <div style={{ marginTop: 16, borderRadius: R.box, overflow: "hidden", border: `1px solid ${DEAL.solid}33`, background: "#FFF7EF" }}>
      <div className="row" style={{ gap: 8, padding: "10px 13px", background: DEAL.bg, justifyContent: "space-between", flexWrap: "wrap" }}>
        <span className="row" style={{ gap: 6, fontSize: 12.5, fontWeight: 800, color: DEAL.ink }}><Tag size={14} />{st === "ending" ? tx("عرض ينتهي قريبًا", "Offer ending soon") : tx("عرض سارٍ", "Active offer")}</span>
        <span className="row" style={{ gap: 6, flexWrap: "wrap" }}>
          {of.exclusive && <Pill tone={T.green} bg={`${T.green}14`} strong>{tx("حصري عبر رحاب المدينة", "Rihab Madinah exclusive")}</Pill>}
          {of.when && <Pill tone={DEAL.ink} bg="#FFFFFF">{WHEN_TAG[of.when]}</Pill>}
        </span>
      </div>
      <div style={{ padding: "12px 13px 13px" }}>
        <div className="row" style={{ gap: 12, alignItems: "flex-start" }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 15.5, fontWeight: 800, lineHeight: 1.5 }}>{L2(of.title)}</div>
            <div style={{ fontSize: 13, color: T.muted, lineHeight: 1.75, marginTop: 3 }}>{L2(of.desc)}</div>
          </div>
          <div style={{ textAlign: "end", flex: "0 0 auto", maxWidth: "42%" }}>
            {of.pct ? <div style={{ fontSize: 24, fontWeight: 800, color: DEAL.solid, lineHeight: 1.1 }}>{tx(`${ar(of.pct)}٪`, `${of.pct}%`)}</div>
              : <div style={{ fontSize: 13, fontWeight: 800, color: DEAL.solid, lineHeight: 1.4, maxWidth: 110 }}>{L2(of.badge)}</div>}
            {p && <div style={{ fontSize: 12.5, fontWeight: 700, marginTop: 3, whiteSpace: "nowrap" }}>{riyal(p.now)} <s style={{ color: T.muted, fontWeight: 600 }}>{riyal(p.was)}</s></div>}
            {p?.pkg && <div style={{ fontSize: 11.5, color: T.muted, fontWeight: 600, marginTop: 2, lineHeight: 1.45 }}>{L2(PKG_NOTE)}</div>}
          </div>
        </div>
        {of.incl.length > 0 && (
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 10 }}>
            {of.incl.map((x, i) => <Pill key={i} tone={T.ink} bg={T.limestone}>{L2(x)}</Pill>)}
          </div>
        )}
        <div style={{ marginTop: 10, display: "grid", gap: 5, fontSize: 12.5, lineHeight: 1.7 }}>
          <div><b>{tx("لمن:", "Who:")}</b> {WHO[of.who]}</div>
          <div><b>{tx("الصلاحية:", "Validity:")}</b> {tx(`حتى ${whenAr(of.end)}`, `Until ${whenMid(of.end)}`)} · {offerExpiry(of)}</div>
          <div><b>{tx("طريقة الاستفادة:", "How to use:")}</b> {REDEEM[of.redeem]}</div>
          <div><b>{tx("الشروط:", "Terms:")}</b> {L2(of.terms)}</div>
        </div>
      </div>
    </div>
  );
}

/* Home / Discover deal rail tile */
/* live deals whose object is promotable, one per object, ranked for this person */
function rankedDeals(ctx, limit = 8, keep) {
  const ids = uniq(liveOffers().map((of) => of.obj)).filter((id) => { const o = getObj(id); return o && isPromotable(o) && (!keep || keep(offerFor(id), o)); });
  return rank(ids.map(getObj), ctx, { limit, maxPerCategory: 3, maxPerNeighborhood: 3 }).map((x) => ({ ...x, of: offerFor(x.o.id) }));
}
function DealTile({ of }) {
  const { go } = useApp();
  const o = getObj(of.obj);
  if (!o) return null;
  const p = offerPrice(of);
  return (
    <button className="lift" onClick={() => go({ s: "object", id: o.id })} style={{ width: "var(--rail-tile)", textAlign: "start", alignSelf: "flex-start" }}>
      <Photo kind={o.scene} seed={o.id} photo={o.photo} ratio="4 / 3" radius={R.media} scrim="soft">
        <div style={{ position: "absolute", insetInlineStart: 8, top: 8, insetInlineEnd: 8 }}><DealBadge of={of} onPhoto /></div>
        {of.exclusive && <div style={{ position: "absolute", insetInlineStart: 8, bottom: 8 }}><Pill tone="#F5F5F2" bg="rgba(23,42,70,.78)" strong size={10}>{tx("حصري عبر رحاب المدينة", "Rihab Madinah exclusive")}</Pill></div>}
      </Photo>
      <div style={{ fontSize: 14, fontWeight: 800, marginTop: 7, lineHeight: 1.45 }}>{o.name}</div>
      <div className="clamp2" style={{ fontSize: 12, color: T.muted, marginTop: 2, lineHeight: 1.55 }}>{L2(of.title)}</div>
      <div style={{ marginTop: 4, fontSize: 12, fontWeight: 700, color: DEAL.ink, lineHeight: 1.5 }}>
        {p ? <>{riyal(p.now)} <s style={{ color: T.muted, fontWeight: 600 }}>{riyal(p.was)}</s>{p.pkg ? <span style={{ color: T.muted, fontWeight: 600 }}> {L2(PKG_NOTE)}</span> : null} · </> : null}
        <span style={{ color: offerStatus(of) === "ending" ? T.warn : T.muted, fontWeight: 600 }}>{offerExpiry(of)}</span>
      </div>
    </button>
  );
}

