    const salaam = /سلام|salam|salaam|assalam/i.test(greet[1]), en = AGENT.prep(greet[2]).lang === "en";
    reply.text = (salaam ? (en ? "Wa alaykum as-salam. " : "وعليكم السلام ورحمة الله. ") : (en ? "Hi! " : "هلا والله! ")) + reply.text;
